import { register, tryResolve } from "./contracts.js";
import { createZodAdapter } from "../../extensions/ext-schema-zod/src/index.js";
/** Ensure the default schema validator is available to schema-backed framework APIs. */
export function ensureBuiltinSchemaValidator() {
    if (!tryResolve("SchemaValidator")) {
        register("SchemaValidator", createZodAdapter());
    }
}
